  const summaries: SessionSummary[] = [
    {sessionId: 's2', createdAt: new Date('2026-01-01T00:00:00.000Z'), updatedAt: new Date('2026-01-01T00:02:00.000Z'), entryCount: 4},
  ];
  const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
  const logs: Array<{category: string; message: string; fields?: Record<string, unknown>}> = [];
  setLogger({...});
  const listing = harness([], {}, storeOf((userId, options) => { seen.push({userId, options}); return summaries; }));
  const unimplemented = harness([], {}, storeOf());
  const failing = harness([], {}, storeOf(() => Promise.reject(new Error('store offline'))));

  await listing.send({type: 'list_sessions', limit: 10, before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'}});
  await unimplemented.send({type: 'list_sessions'});
  await failing.send({type: 'list_sessions'});
  setLogger();

  expect({asked: seen, listed: listing.sent, empty: unimplemented.frames(), failed: failing.frames(), logged: logs}).toEqual({
    asked: [{userId: 'u1', options: {limit: 10, before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'}}}],
