  beforeEach(() => {
    errors.length = 0;
    setLogger({
      debug: quiet,
      info: quiet,
      warn: quiet,
      error: (category, message, fields) => void errors.push({category, message, ...fields}),
    });
  });

  afterEach(() => setLogger());

  return errors;
}
