// A store double of the five required members alone, so listFor is present, absent or failing by construction.
const storeOf = (listFor?: SessionStore['listFor']): SessionStore =>
  {...(listFor ? {listFor} : {})} as unknown as SessionStore;

describe('a list_sessions frame', () => {
  const errors = captureErrors();

  it('answers list_sessions with the summaries of the session user as ISO dates, an empty list without a listFor, and SERVER_ERROR when the store throws', async () => {
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const listing = harness(
      [],
      {},
      storeOf((userId, options) => {
        seen.push({userId, options});
        return summaries;
      })
    );
    const unimplemented = harness([], {}, storeOf());
    const failing = harness([], {}, storeOf(() => Promise.reject(new Error('store offline'))));

    try {
      await listing.send({type: 'list_sessions', limit: 10, before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'}});
      await unimplemented.send({type: 'list_sessions'});
      await failing.send({type: 'list_sessions'});
    } finally {
      void errors;
    }

    expect({asked: seen, listed: listing.sent, empty: unimplemented.frames(), failed: failing.frames(), logged: errors}).toEqual({
      asked: [{userId: 'u1', options: {limit: 10, before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'}}}],
      listed: [
        {
          type: 'session_list',
          sessions: [
            {sessionId: 's2', createdAt: '2026-01-01T00:00:00.000Z', updatedAt: '2026-01-01T00:02:00.000Z', entryCount: 4},
          ],
        },
      ],
      empty: ['session_list'],
      failed: ['error SERVER_ERROR'],
      logged: [{category: 'ws', message: expect.any(String), userId: 'u1', error: 'store offline'}],
    });
  });
});

// One real turn through the handler: the model asks for `call` and, handed its result, answers.
async function turnOver(call: ToolCall, registry: ToolRegistry): Promise<string[]> {
  let requests = 0;
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      requests++;
      const asks: MessageChunk[] = [
        {type: 'tool_use', toolCall: call},
        {type: 'stop', stopReason: 'tool_use'},
      ];
      yield* requests === 1 ? asks : [text('all done'), STOP];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Failure test.'}), registry);
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

  await createMessageHandler(orchestrator)(ws, session, userMessage('hello'));
  return wire(sent);
}

// What the client saw of the turn: whether the answer streamed, the last frame, and any error frames.
function outcomeOf(frames: string[]): {answered: boolean; last: string | undefined; errors: string[]} {
  return {
    answered: frames.some(frame => frame.startsWith('delta') && frame.endsWith(JSON.stringify('all done'))),
    last: frames.at(-1),
    errors: frames.filter(frame => frame.startsWith('error')),
  };
}

