// Every frame but a user_message answers here, off the per-session lock: a list changes nothing and must not queue behind a turn.
async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore: SessionStore | undefined
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') await handleListSessions(ws, session, sessionStore, message);
}

// The list is always the session user's: the id comes from the connection, never from the frame.
async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  try {
    const summaries =
      (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSummaryFrame)});
  } catch (error) {
    const detail = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'conversation list failed', {sessionId: session.sessionId, userId: session.userId, error: detail});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
  }
}
